const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

const body = $input.first().json.body || $input.first().json;
return [{ json: body }];

// ── Consolidate trigger payload + DB lead context ────────────────────────
const trigger = $items('Set Idempotency Key')[0].json;
const lead    = $input.first().json;

if (!lead || !lead.id) {
  throw new Error(`LEAD_NOT_FOUND: ${trigger.lead_id}`);
}

const parseCol = (v) => {
  if (!v) return {};
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch(e) { return {}; }
};

const brief            = parseCol(lead.brief);
const scoreBreakdown   = parseCol(lead.score_breakdown);
const triggerContext   = parseCol(trigger.context);
const recentConvos     = lead.recent_conversations || [];

// Format conversation history for AI prompt
const convoLines = (Array.isArray(recentConvos) ? recentConvos : [])
  .slice(0, 5)
  .map(c => `[${c.direction === 'outbound' ? 'US' : 'LEAD'} @ ${(c.sent_at||'').slice(0,10)}] ${(c.body_text||'').slice(0,300)}`)
  .join('\n');

// Build full context string for the briefing prompt
const fullContext = [
  `LEAD: ${lead.full_name || lead.email} | ${lead.title} at ${lead.company}`,
  `TIER: ${lead.tier} | SCORE: ${lead.score} | STATUS: ${lead.status}`,
  `INDUSTRY: ${lead.industry || 'Unknown'} | SIZE: ${lead.employee_count || '?'} employees`,
  `ESCALATION REASON: ${trigger.reason || 'unspecified'}`,
  `SOURCE WORKFLOW: ${triggerContext.workflow || trigger.source_workflow || 'unknown'}`,
  `URGENCY: ${triggerContext.urgency || 'MEDIUM'}`,
  triggerContext.intent     ? `INTENT CLASSIFIED: ${triggerContext.intent}` : '',
  triggerContext.reply_summary ? `REPLY SUMMARY: ${triggerContext.reply_summary}` : '',
  triggerContext.reply_draft   ? `DRAFT REPLY (if any):\n${triggerContext.reply_draft}` : '',
  triggerContext.flags         ? `GUARDRAIL FLAGS: ${(triggerContext.flags||[]).join(', ')}` : '',
  brief.outreach_angles ? `OUTREACH ANGLES: ${(brief.outreach_angles||[]).slice(0,2).join('; ')}` : '',
  convoLines ? `\nRECENT CONVERSATION:\n${convoLines}` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ...lead,
    ...trigger,
    lead_id:               lead.id,
    brief,
    score_breakdown:       scoreBreakdown,
    trigger_context:       triggerContext,
    full_context:          fullContext.slice(0, 4000),
    open_escalation_count: parseInt(lead.open_escalation_count || 0),
    urgency:               triggerContext.urgency || 'MEDIUM',
    source_workflow:       triggerContext.workflow || trigger.source_workflow || 'unknown',
    escalation_reason:     trigger.reason || 'unspecified'
  }
}];

