const ctx          = $items('Consolidate Context')[0].json;
const escRecord    = $input.first().json;

return [{
  json: {
    ...ctx,
    escalation_id:  escRecord.escalation_id,
    escalation_created_at: escRecord.created_at
  }
}];

// ── Parse the AI briefing JSON response ──────────────────────────────────
const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let briefing = {};
try {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('no JSON');
  briefing = JSON.parse(raw.slice(s, e + 1));
} catch(_) {
  // Graceful fallback — construct a minimal briefing from raw context
  const ctx = $items('Attach Escalation ID')[0].json;
  briefing = {
    headline:            `${ctx.escalation_reason} — ${ctx.full_name || ctx.email} at ${ctx.company}`,
    bullets:             [
      `Tier ${ctx.tier} lead, score ${ctx.score}`,
      `Status: ${ctx.status}`,
      `Source workflow: ${ctx.source_workflow}`,
      `Urgency: ${ctx.urgency}`,
      `Reason: ${ctx.escalation_reason}`
    ],
    discovery_questions: [
      'What specific concerns do you have?',
      'What would need to be true for this to move forward?',
      'Who else is involved in this decision?'
    ],
    recommended_action:  'Review conversation history and reach out directly',
    urgency:             ctx.urgency || 'MEDIUM',
    tone_guidance:       'Approach with care — review context before responding'
  };
}

const ctx = $items('Attach Escalation ID')[0].json;

// Format bullets as a numbered list for Slack
const bulletLines = (briefing.bullets || [])
  .slice(0, 5)
  .map((b, i) => `${i + 1}. ${b}`)
  .join('\n');

const questionLines = (briefing.discovery_questions || [])
  .slice(0, 3)
  .map((q, i) => `${i + 1}. ${q}`)
  .join('\n');

// Build the review URL (points to a simple resolution handler webhook)
const reviewUrl = `${$env.N8N_WEBHOOK_BASE_URL}/webhook/escalation-resolve`;

return [{
  json: {
    ...ctx,
    briefing_headline:     briefing.headline          || '',
    briefing_bullets:      briefing.bullets           || [],
    briefing_questions:    briefing.discovery_questions || [],
    briefing_action:       briefing.recommended_action || '',
    briefing_urgency:      briefing.urgency            || ctx.urgency || 'MEDIUM',
    briefing_tone:         briefing.tone_guidance      || '',
    bullet_lines:          bulletLines,
    question_lines:        questionLines,
    review_url:            reviewUrl,
    urgency_emoji:         briefing.urgency === 'HIGH' ? '🔴' : briefing.urgency === 'MEDIUM' ? '🟡' : '🟢'
  }
}];

