// ── Parse Slack interactive message payload ───────────────────────────────
// Slack sends a URL-encoded 'payload' field with the action data.
// The payload contains actions[], user info, and the original block value.

const body = $input.first().json.body || $input.first().json;

// Slack sends payload as URL-encoded string in body.payload
let slackPayload = {};
try {
  const raw = body.payload || body;
  slackPayload = typeof raw === 'string' ? JSON.parse(decodeURIComponent(raw)) : raw;
} catch(e) {
  throw new Error('SLACK_PARSE_FAILED: ' + e.message);
}

const action    = slackPayload.actions?.[0] || {};
const actionId  = action.action_id || '';
const valueRaw  = action.value     || '{}';
const user      = slackPayload.user || {};
const msgTs     = slackPayload.message?.ts || slackPayload.container?.message_ts || null;
const channelId = slackPayload.channel?.id || null;

let actionValue = {};
try { actionValue = JSON.parse(valueRaw); } catch(_) {}

const actionType = actionValue.action || actionId.replace('_escalation', '');

return [{
  json: {
    escalation_id:  actionValue.escalation_id || null,
    lead_id:        actionValue.lead_id        || null,
    action_type:    actionType,   // approve | edit | takeover
    ae_user_id:     user.id       || null,
    ae_username:    user.username || user.name || 'unknown',
    ae_real_name:   user.real_name || '',
    slack_ts:       msgTs,
    slack_channel:  channelId,
    received_at:    new Date().toISOString()
  }
}];

