  json: {
    ...esc,
    slack_ts:         ctx.slack_ts      || null,
    slack_channel:    ctx.slack_channel || $env.SLACK_ESCALATION_CHANNEL || '#agent-x-escalations',
    briefing_action:  ctx.briefing_action || 'Review and respond to this lead',
    hours_pending:    hoursSince,
    urgency:          ctx.briefing_urgency || 'MEDIUM',
    urgency_emoji:    (ctx.briefing_urgency === 'HIGH') ? '🔴' : '🟡'
  }
}];

