const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-09';

return [{
  json: {
    status:       msg.includes('UNAUTHORIZED') ? 'unauthorized' :
                  msg.includes('LEAD_NOT_FOUND') ? 'lead_not_found' :
                  msg.includes('SLACK_PARSE') ? 'parse_error' : 'error',
    message:      msg,
    workflow:     'WF-09',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];

// ── Slack signature verification ─────────────────────────────────────────
// Validates X-Slack-Signature and X-Slack-Request-Timestamp headers.
// Protects against spoofed requests to /webhook/escalation-resolve.
//
// Reference: https://api.slack.com/authentication/verifying-requests-from-slack
//
// Required env var: SLACK_SIGNING_SECRET (from Slack app → Basic Information)

const body    = $input.first().json;
const headers = body.headers || {};

const slackSig       = headers['x-slack-signature']        || headers['X-Slack-Signature']        || '';
const slackTimestamp = headers['x-slack-request-timestamp'] || headers['X-Slack-Request-Timestamp'] || '';
const rawBody        = body.rawBody || body.body || '';

// ── Step 1: Reject missing headers ───────────────────────────────────────
if (!slackSig || !slackTimestamp) {
  throw new Error('SLACK_SIGNATURE_MISSING: required headers not present');
}

// ── Step 2: Reject stale requests (replay attack protection) ─────────────
// Slack recommendation: reject if timestamp is > 5 minutes old
const nowSeconds  = Math.floor(Date.now() / 1000);
const tsDiff      = Math.abs(nowSeconds - parseInt(slackTimestamp, 10));
if (tsDiff > 300) {
  throw new Error(`SLACK_TIMESTAMP_STALE: request is ${tsDiff}s old (max 300s)`);
}

// ── Step 3: Compute expected signature ───────────────────────────────────
const signingSecret = $env.SLACK_SIGNING_SECRET;
if (!signingSecret) {
  throw new Error('SLACK_SIGNING_SECRET env var not configured');
}

// Build the base string Slack uses for signing
const baseString = `v0:${slackTimestamp}:${rawBody}`;

// HMAC-SHA256 using Node.js crypto (available in n8n Function nodes)
const crypto    = require('crypto');
const hmac      = crypto.createHmac('sha256', signingSecret);
hmac.update(baseString);
const computed  = 'v0=' + hmac.digest('hex');

// ── Step 4: Timing-safe comparison (prevents timing attacks) ─────────────
const sigBuffer      = Buffer.from(slackSig, 'utf8');
const computedBuffer = Buffer.from(computed, 'utf8');

const signaturesMatch =
  sigBuffer.length === computedBuffer.length &&
  crypto.timingSafeEqual(sigBuffer, computedBuffer);

if (!signaturesMatch) {
  throw new Error('SLACK_SIGNATURE_INVALID: signature mismatch — possible spoofed request');
}

// Signature valid — pass body through to Parse Slack Action
return [{ json: body }];
